data.query:
query Load($where: LoadWhereInput, $orderBy: [LoadOrderByInput!], $first: Int, $after: String) {
  load(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        trailerNumber
        sealNumber
        arrivalAt
        note
        scacId
      }
    }
  }
}

data.transform:
/* {
 "payload": [
  {
    "update": {
      "asnNumber": asn,
      "trackingNumber": trackingNumber,
      "bolNumber": bolNumber,
      "proNumber": proNumber,
      "shipAt": shipAt,
      "note": note
    },
    "where": {"id": $state.context.input.shipmentId}
  }
 ] 
} */


(
  $fields := {
    "asnNumber": asn,
    "trackingNumber": trackingNumber,
    "bolNumber": bolNumber,
    "proNumber": proNumber,
    "shipAt": shipAt,
    "note": note
  };
  {
    "payload": [
      {
        "update": $merge($fields.$each(function($v, $k) {
          $v != null ? {$k: $v} : {}
        })),
        "where": {"id": $state.context.input.shipmentId}
      }
    ]
  }
)

data.query:
query Pick($where: PickWhereInput, $orderBy: [PickOrderByInput!], $first: Int, $after: String) {
  pick(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        scheduledStartAt
        load {
          id
          number
          orders {
            total
            edges {
              node {
                id
                number
              }
            }
          }
        }
        pickSteps {
          edges {
            node {
              id
              quantity {
                value
                unitId
              }
              orderLineRelease {
                orderLine {
                  product {
                    name
                    description
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
$exists($state.context.input.loadId) ?
  /* prepare the variables logic for the query to search by loadId */
  {
    "where":{
      "id":{
        "_eq": $state.context.input.loadId
      }
    }
  } 
  :
  /* prepare the variables logic for the query to search by orderId */
  {
    "where":{
      "orders":{
        "_some":{
          "id":{
            "_eq": $state.context.input.orderId
          }
        }
      }
    }
  }

