data.transform:
(
  $pickData := pick.edges.node;
  $pickStepsData := $pickData.pickSteps.edges.node;

  {
    "header": $pickData.{
      "orderNumber": load.orders.total = 1 ?
        load.orders.edges[0].node.number : $join(load.orders.edges.node.number, ", "),
      "loadNumber": load.number,
      "pickNumber": number,
      "scheduledStartAt": scheduledStartAt
    },
    "data": $pickStepsData.{
      "productName": orderLineRelease.orderLine.product.name,
      "productDescription": orderLineRelease.orderLine.product.description,
      "quantity": quantity.value & " " & quantity.unitId,
      "dropZone": "?"
    }
  }
)

