query Order($where: OrderWhereInput, $orderBy: [OrderOrderByInput!], $first: Int, $after: String) {
  order(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        orderLines {
          edges {
            node {
              id
              productId
              product {
                id
                code
                name
              }
              orderLineReleases {
                edges {
                  node {
                    id
                    quantity {
                      value
                      unitId
                    }
                    pickSteps {
                      edges {
                        node {
                          id
                          quantity {
                            value
                            unitId
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $pickId := $state.context.input.pickId;
  $orderId := $state.context.input.orderId;
  $lines := [$.order.edges.node.orderLines.edges.node];

  $missingPickSteps := $reduce($map($lines, function($line) {
    $map([$line.orderLineReleases.edges.node], function($olr) {
      (
        $required := $olr.quantity.value;
        $unitId := $olr.quantity.unitId;
        $assigned := $exists($olr.pickSteps.edges.node) ? $sum($olr.pickSteps.edges.node.quantity.value) : 0;
        $assigned < $required ? {
          "id": $olr.id,
          "pickId": $pickId,
          "quantity": $required,
          "unitId": $unitId,
          "required": $required,
          "productId": $line.productId,
          "productCode": $line.product.code,
          "assigned": $assigned,
          "remaining": $required - $assigned
        } : undefined
      )
    })
  }), function($a, $b) { $append($a, $b) });

  $count($missingPickSteps) > 0 ?
    $map($missingPickSteps, function($step) {
      $merge([
        $executeFlow("createPickStep", {
          "pickId": $pickId,
          "productId": $step.productId,
          "quantity": $step.required,
          "assignedQuantity": $step.assigned,
          "orderLineReleaseId": $step.id
        }),
        {
          "productCode": $step.productCode,
          "quantity": $step.quantity,
          "unitId": $step.unitId
        }
      ])
    })
  : undefined;
)

data.messageTransform:
(
  $results := $state.context.createPickStepResults;
  $failures := $exists($results) ? $results[success = false] : [];
  $count($failures) > 0
    ? $join($failures.("Product " & productCode & " (" & quantity & " " & unitId & ")" & ": " & message), "\n")
    : "All missing pick steps were created successfully."
)

